    "fuente": "PAU 2025/EXÁMENES AÑOS ANTERIORES/2020/biologia_P_6.pdf",
    "criterios": "PAU 2025/EXÁMENES AÑOS ANTERIORES/2020/biologia_C_6.pdf",
    "examen_anio": 2020,
    "verificado": true
